const EMERALD_B = [
  { title: "The Silent Spring", text: ["In 1962, an American scientist called Rachel Carson published a book that changed the way people thought about the natural world. It was called Silent Spring.", "Carson, who had spent years studying wildlife, had noticed something disturbing. In towns where chemical pesticides were sprayed to kill insects, birds were disappearing. The pesticides, which entered the food chain through the insects the birds ate, were poisoning them. Carson imagined a future spring in which no birdsong could be heard at all.", "Chemical companies attacked her fiercely. They claimed that she was exaggerating, that she was not a proper scientist, and that, if people listened to her, crops would fail and diseases would spread. Some even tried to stop the book being published.", "But Carson's evidence was careful and convincing. Ordinary readers, alarmed by what they read, began to demand change. Within ten years, the most dangerous pesticide, DDT, had been banned in the USA, and governments around the world had begun to take the protection of the environment seriously.", "Carson did not live to see this. She died in 1964. But many people consider Silent Spring to be the beginning of the modern environmental movement."],
    q: [["What had Carson noticed?", ["Birds were disappearing where pesticides were sprayed.", "Insects were getting bigger.", "Crops were failing."], 0, "retrieval"], ["How did the pesticides harm birds?", ["They entered the food chain through the insects the birds ate.", "They were sprayed directly on nests.", "They made the weather colder."], 0, "retrieval"], ["How did chemical companies respond?", ["They attacked her and claimed she was exaggerating.", "They agreed and stopped selling pesticides.", "They ignored the book."], 0, "retrieval"], ["What does the title \"Silent Spring\" refer to?", ["a future spring with no birdsong", "a quiet stream", "a peaceful holiday"], 0, "inference"], ["What is the writer's attitude to Carson?", ["admiring", "critical", "neutral and uninterested"], 0, "inference"]] },
  { title: "Dear Diary", text: ["Saturday", "Well, that was a total disaster. I mean, honestly, what was I thinking?", "So there's this talent show at school, right, and Priya and I decided we'd do a magic act. We practised for, like, three weeks. We had capes. We had a wand. We even had a real rabbit, borrowed from Priya's cousin, called Mr Biscuits.", "Everything was going brilliantly until the big finale, when I was supposed to pull Mr Biscuits out of the hat. Except Mr Biscuits had other ideas. He'd escaped through a gap in the table and was hopping calmly across the stage towards the head teacher, who was sitting in the front row in her best suit.", "The whole hall went silent. Then Mr Biscuits sat down on Mrs Fairweather's foot and started washing his ears.", "And then everybody — and I mean everybody — burst out laughing. Including Mrs Fairweather!", "We didn't win. But we did get a special prize for \"Best Comedy Act\", which, to be fair, is probably what we deserved all along."],
    q: [["What act did the writer and Priya do?", ["a magic act", "a dance", "a song"], 0, "retrieval"], ["Who was Mr Biscuits?", ["a rabbit", "a teacher", "Priya's cousin"], 0, "retrieval"], ["Which feature shows this is informal?", ["chatty phrases like \"So there's this talent show, right\"", "formal vocabulary", "a list of facts"], 0, "language"], ["How did Mrs Fairweather react?", ["She laughed.", "She was furious.", "She left the hall."], 0, "retrieval"], ["How does the writer feel by the end?", ["amused and able to see the funny side", "still very upset", "angry with Priya"], 0, "inference"]] },
  { title: "Notice to Residents", text: ["NOTICE TO ALL RESIDENTS: HIGH STREET IMPROVEMENT WORKS", "Residents are advised that improvement works will take place on the High Street between Monday 3rd March and Friday 25th April. During this period, the road will be closed to all traffic between Church Lane and Market Square.", "The works, which have been planned in consultation with local businesses, will include the widening of pavements, the installation of new street lighting and the planting of twenty trees.", "It is requested that residents park only in designated areas and that vehicles not be left on the High Street after 6 p.m. on Sunday 2nd March. Any vehicle remaining will be removed.", "The council apologises for any inconvenience caused and thanks residents for their patience. Further information may be obtained from the council offices or the council website."],
    q: [["When will the works finish?", ["Friday 25th April", "Monday 3rd March", "Sunday 2nd March"], 0, "retrieval"], ["Which part of the High Street will be closed?", ["between Church Lane and Market Square", "the whole High Street", "only Market Square"], 0, "retrieval"], ["Name one improvement that will be made.", ["the planting of twenty trees", "a new swimming pool", "a new school"], 0, "retrieval"], ["What will happen to vehicles left on the High Street?", ["They will be removed.", "They will be fined later.", "Nothing."], 0, "retrieval"], ["Which features show the notice is formal?", ["passive verbs and phrases like \"Residents are advised\"", "jokes and slang", "first-person storytelling"], 0, "language"]] }
];
const EREG = { focus: "Register and tone", explain: "Register is how formal or informal language is. Tone is the attitude it shows: serious, playful, angry, warm or neutral. Writers choose vocabulary, sentence structures and punctuation to suit their audience and purpose." };
const ECOMP = { focus: "Complex sentences", explain: "A complex sentence has a main clause and at least one subordinate clause (starting with words such as although, because, which, who, while or if). Subordinate clauses add detail, reasons and conditions, and can go at the start, in the middle or at the end." };
const ESUBJ = { focus: "The subjunctive in formal writing", explain: "The subjunctive is used in very formal writing for wishes, demands and imagined situations: If I were you… / It is essential that every pupil be on time. / The council requests that cars not be parked here." };
const eregP = [["Which sentence is most formal?", ["We regret to inform you that the event has been postponed.", "Bad news: the event's off!", "So, yeah, no event."], 0], ["What is the tone of \"Well, that was a total disaster!\"?", ["chatty and exasperated", "formal and neutral", "scientific"], 0], ["Which word belongs in a formal report?", ["consequently", "basically", "kind of"], 0]];
const ecompP = [["Which is a complex sentence?", ["Although it was raining, the match continued.", "It was raining. The match continued.", "It was raining and the match continued."], 0], ["In \"The bridge, which was built in 1890, is closing\", what is the subordinate clause?", ["which was built in 1890", "The bridge", "is closing"], 0], ["Which word often starts a subordinate clause?", ["because", "and", "but"], 0]];
const esubjP = [["Which uses the subjunctive?", ["If I were taller, I could reach.", "If I was taller, I could reach.", "I am tall."], 0], ["Choose the formal subjunctive: \"It is vital that he ___ told.\"", ["be", "is", "was"], 0], ["Where are you most likely to find the subjunctive?", ["in formal writing such as notices and speeches", "in text messages", "in shopping lists"], 0]];
const EMERALD_TEXTS = [
  { id: "em18-mary", band: 18, title: "Mary Anning, Fossil Hunter", type: "Biography", text: ["Mary Anning was born in 1799 in Lyme Regis, a small town on the south coast of England whose crumbling cliffs are packed with fossils. Her family was poor, and to earn money they collected fossils from the beach, which they sold to tourists as curiosities.", "When Mary was only twelve, she and her brother discovered the skeleton of a strange creature, over five metres long, which had lain in the cliffs for nearly 200 million years. It was an ichthyosaur, a marine reptile that had lived at the time of the dinosaurs. Although she had no formal education, Mary taught herself geology and anatomy so thoroughly that leading scientists travelled to Lyme Regis to consult her.", "Over the following decades, she made discovery after discovery, including the first complete plesiosaur ever found. Her finds helped to prove that animals could become extinct, an idea that was shocking at the time.", "Yet because she was a woman, and because she was not wealthy, she was never allowed to join the Geological Society of London, and men often published her discoveries under their own names. It was not until long after her death in 1847 that her achievements were properly recognised.", "Today, she is celebrated as one of the most important fossil hunters in history."],
    vocab: { curiosities: "unusual objects people find interesting", geology: "the study of rocks and the Earth", anatomy: "the study of the structure of bodies" },
    questions: [["Why did Mary's family collect fossils?", ["to sell to tourists for money", "to give to museums", "as a hobby"], 0, "retrieval"], ["What did Mary discover at the age of twelve?", ["an ichthyosaur skeleton", "a plesiosaur", "a dinosaur egg"], 0, "retrieval"], ["Why did her discoveries matter?", ["They helped to prove that animals could become extinct.", "They proved dinosaurs could fly.", "They made Lyme Regis rich."], 0, "retrieval"], ["Why was Mary not allowed to join the Geological Society?", ["She was a woman and was not wealthy.", "She was too young.", "She lived too far away."], 0, "retrieval"], ["What is the writer's view of how Mary was treated?", ["that it was unfair", "that it was deserved", "that it does not matter"], 0, "inference"]],
    grammar: Object.assign({}, ECOMP, { spots: ["whose crumbling cliffs are packed with fossils", "which they sold to tourists as curiosities", "which had lain in the cliffs for nearly 200 million years", "Although she had no formal education,", "because she was a woman, and because she was not wealthy,"], practice: ecompP }) },
  { id: "em18-review", band: 18, title: "Two Reviews of the Same Film", type: "Reviews", text: ["Review 1: The Daily Standard", "The Ice Kingdom, the latest animated feature from Polaris Studios, is a visually stunning but ultimately hollow experience. While the animation of the frozen landscapes is undeniably breathtaking, the plot relies heavily on familiar clichés, and the characters, with the exception of the witty snow-fox Pip, lack depth. Younger viewers may be entertained; adults are likely to find their attention wandering long before the predictable conclusion. Two stars.", "Review 2: Kids' Corner blog, by Zara, aged 11", "OK, so I just saw The Ice Kingdom and I LOVED it!!! The snow looked so real I actually felt cold. Pip the snow-fox is literally the funniest character ever — I was laughing so much my brother told me to shush. There's a bit near the end where you think everything's going to go wrong and I was hiding behind my popcorn. My mum said the story was \"a bit predictable\", but honestly, who cares? Five stars from me. Go and see it!"],
    vocab: { clichés: "ideas or phrases used so often they are no longer interesting", predictable: "easy to guess before it happens", hollow: "here, without real meaning or depth" },
    questions: [["What do both reviewers praise?", ["the animation and the character Pip", "the plot", "the ending"], 0, "inference"], ["What is the Daily Standard's main criticism?", ["The plot is full of clichés and the characters lack depth.", "The animation is poor.", "It is too short."], 0, "retrieval"], ["How does Zara react to her mum's criticism?", ["She doesn't think it matters.", "She agrees completely.", "She changes her rating."], 0, "retrieval"], ["Which phrase from Review 1 shows a formal register?", ["undeniably breathtaking", "I LOVED it", "who cares?"], 0, "language"], ["Why are the two reviews so different in tone?", ["They are written by different people for different audiences.", "They are about different films.", "One is a mistake."], 0, "inference"]],
    grammar: Object.assign({}, EREG, { spots: ["visually stunning but ultimately hollow experience", "undeniably breathtaking", "relies heavily on familiar clichés", "adults are likely to find their attention wandering", "OK, so I just saw The Ice Kingdom and I LOVED it!!!", "literally the funniest character ever", "honestly, who cares?", "Go and see it!"], practice: eregP }) },
  { id: "em18-apology", band: 18, title: "The Formal Complaint", type: "Letter", text: ["Dear Sir or Madam,", "I am writing to express my dissatisfaction with the service I received at your Riverside branch on Saturday 14th June.", "Having booked a table for six people to celebrate my grandmother's eightieth birthday, I was dismayed to discover, on arrival, that no record of our booking could be found. Although the staff eventually found us a table, it was beside the kitchen door, which opened and closed constantly throughout the meal.", "Furthermore, the birthday cake that I had ordered in advance did not appear, and when I enquired about it, a member of staff responded in a manner that I can only describe as dismissive.", "I would ask that you investigate this matter and that the staff involved be reminded of the importance of courtesy. I should also be grateful if you would consider a partial refund, given that what should have been a joyful occasion was, in many respects, spoiled.", "I look forward to your reply.", "Yours faithfully,", "Imran Siddiqui"],
    vocab: { dissatisfaction: "a feeling of being unhappy with something", dismissive: "showing that you think something is not worth considering", courtesy: "polite and respectful behaviour" },
    questions: [["What was the occasion?", ["his grandmother's eightieth birthday", "his own birthday", "a wedding"], 0, "retrieval"], ["What went wrong with the booking?", ["There was no record of it.", "It was for the wrong day.", "The restaurant was closed."], 0, "retrieval"], ["What does Mr Siddiqui ask the restaurant to do?", ["investigate, remind staff about courtesy and consider a partial refund", "close the branch", "send a new cake"], 0, "retrieval"], ["What is the tone of the letter?", ["formal, controlled and disappointed", "angry and rude", "light-hearted"], 0, "language"], ["Why does he end with \"Yours faithfully\"?", ["because he began with \"Dear Sir or Madam\"", "because he is angry", "because it is a friendly letter"], 0, "structure"]],
    grammar: Object.assign({}, ESUBJ, { spots: ["I would ask that you investigate this matter and that the staff involved be reminded of the importance of courtesy", "I should also be grateful if you would consider a partial refund"], practice: esubjP }) },
  { id: "em18-desert", band: 18, title: "Crossing the Empty Quarter", type: "Recount", text: ["The Rub' al Khali, or Empty Quarter, is the largest continuous sand desert on Earth. Covering parts of Saudi Arabia, Oman, the UAE and Yemen, it stretches for over 650,000 square kilometres, an area larger than France.", "In 1930, the British explorer Bertram Thomas became the first outsider known to have crossed it, guided by Bedouin companions whose knowledge of the desert was extraordinary. They could read the landscape as easily as a book, recognising individual camels by their footprints and finding water where none appeared to exist.", "The journey took fifty-eight days. Temperatures during the day often climbed above fifty degrees Celsius, while at night they could fall close to freezing. Dunes, some of which rose to 250 metres, had to be climbed and descended again and again, and when sandstorms swept across the desert, the travellers had no choice but to crouch beside their camels and wait.", "Thomas later wrote that, although he received the credit, the true achievement belonged to the Bedouin, without whom the crossing would have been impossible. His companions, he said, had taught him that in the desert, survival depended not on strength but on patience, knowledge and trust."],
    vocab: { continuous: "without a break", Bedouin: "Arab people who traditionally live and travel in the desert", descended: "went down" },
    questions: [["How big is the Empty Quarter?", ["over 650,000 square kilometres", "about the size of London", "65 square kilometres"], 0, "retrieval"], ["What skills did the Bedouin guides have?", ["recognising camels by footprints and finding water", "building boats", "reading maps"], 0, "retrieval"], ["How long did the journey take?", ["fifty-eight days", "fifty days", "one year"], 0, "retrieval"], ["What did Thomas believe about the achievement?", ["It really belonged to the Bedouin.", "It was his alone.", "It was easy."], 0, "inference"], ["According to the text, what did survival depend on?", ["patience, knowledge and trust", "strength and speed", "money and equipment"], 0, "summarising"]],
    grammar: Object.assign({}, ECOMP, { spots: ["Covering parts of Saudi Arabia, Oman, the UAE and Yemen,", "whose knowledge of the desert was extraordinary", "while at night they could fall close to freezing", "some of which rose to 250 metres", "when sandstorms swept across the desert", "although he received the credit", "without whom the crossing would have been impossible"], practice: ecompP }) },
  { id: "em18-speech", band: 18, title: "Head Girl's Farewell Speech", type: "Speech", text: ["Mrs Okafor, teachers, parents and, above all, my fellow Year 6s: thank you.", "Seven years ago, many of us walked through those gates for the first time, clutching our parents' hands and wondering whether we would ever find the toilets. Today, we walk out of them, I hope, a little taller, a little wiser and a great deal louder.", "We have learned a great many things here: long division, the water cycle, the six wives of Henry VIII. But I believe the most important lessons were the ones that were never on the timetable. We learned that it is all right to get things wrong, provided we try again. We learned that kindness is not a weakness. And we learned that every single person in this room has something to offer, even if, like me, it took them until Year 4 to discover what it was.", "To our teachers: you believed in us even when we did not believe in ourselves. We will not forget it.", "If I were to give one piece of advice to the Year 5s who will take our place, it would be this: be brave, be curious and be kind. The rest will follow.", "Thank you."],
    vocab: { clutching: "holding tightly", timetable: "a plan showing when lessons happen" },
    questions: [["Who is the speech mainly addressed to?", ["the other Year 6 pupils", "only the teachers", "the Year 5s"], 0, "inference"], ["What does the speaker say were the most important lessons?", ["the ones that were never on the timetable", "long division", "the water cycle"], 0, "retrieval"], ["Why does she mention finding the toilets?", ["to add humour and show how small they were at first", "because the toilets were lost", "to complain about the school"], 0, "language"], ["What is her advice to the Year 5s?", ["be brave, be curious and be kind", "work harder", "find the toilets"], 0, "retrieval"], ["How would you describe the tone of the speech?", ["warm, grateful and lightly humorous", "angry", "cold and formal"], 0, "language"]],
    grammar: Object.assign({}, EREG, { spots: ["Mrs Okafor, teachers, parents and, above all, my fellow Year 6s: thank you.", "a little taller, a little wiser and a great deal louder", "kindness is not a weakness", "you believed in us even when we did not believe in ourselves", "If I were to give one piece of advice"], practice: eregP }) },
  { id: "em18-rescue", band: 18, title: "The Rescue", type: "Story", text: ["Had it not been for the dog, nobody would have found them.", "The search had been going on for nine hours. Two teenagers, who had set out that morning to walk the coastal path, had failed to return, and as darkness fell and the rain thickened into a cold, driving sleet, the rescue team had begun to fear the worst.", "Bramble, a border collie who had been trained to find people by scent, was the youngest dog on the team. Her handler, Sam, had doubted whether she was ready for a real search. But when they reached the top of a steep, crumbling gully that the others had already checked twice, Bramble stopped, lifted her nose and began to whine.", "\"There's nothing down there,\" said one of the team. \"We've looked.\"", "Sam hesitated. Then, trusting the dog rather than the map, he clipped on a rope and climbed down. Thirty metres below, wedged beneath an overhang of rock where they had sheltered from the weather, he found the two teenagers, cold and frightened but alive.", "Later, when people asked Sam how they had been found, he simply pointed at the small, muddy dog asleep by the fire. \"Ask her,\" he said."],
    vocab: { gully: "a narrow, steep channel cut into a hillside", overhang: "a part of a rock that sticks out over the space below", handler: "the person who works with and controls a trained animal" },
    questions: [["How long had the search been going on?", ["nine hours", "two days", "thirty minutes"], 0, "retrieval"], ["Why had Sam doubted Bramble?", ["She was the youngest dog and he wasn't sure she was ready.", "She was ill.", "She was not trained."], 0, "retrieval"], ["Why did the others think there was nothing in the gully?", ["They had already checked it twice.", "It was too small.", "It was full of water."], 0, "retrieval"], ["What is the effect of the opening sentence?", ["It hooks the reader by revealing that the dog is the key to the story.", "It describes the weather.", "It ends the story."], 0, "structure"], ["What does \"Ask her\" show about Sam?", ["He gives all the credit to Bramble.", "He is joking that dogs can talk.", "He is annoyed by the questions."], 0, "inference"]],
    grammar: Object.assign({}, ECOMP, { spots: ["Had it not been for the dog,", "who had set out that morning to walk the coastal path", "as darkness fell and the rain thickened into a cold, driving sleet", "who had been trained to find people by scent", "that the others had already checked twice", "where they had sheltered from the weather"], practice: ecompP }) },
  { id: "em18-rules", band: 18, title: "Library Rules: Two Versions", type: "Notices", text: ["Version 1 (for the library noticeboard)", "Silver Birch Library: Conditions of Use", "Visitors are reminded that this is a quiet study area. It is requested that mobile phones be switched to silent and that conversations be kept to a minimum.", "Food and drink, with the exception of water in a sealed bottle, are not permitted. Borrowers are responsible for any damage to items in their care, and items returned late will incur a charge of 10p per day.", "Version 2 (for the children's section)", "Hello, book explorers!", "Welcome to our library. Here's how to make it a great place for everyone:", "Shhh! Use your quietest voice so that everyone can enjoy their books.", "Snacks stay in your bag. (A bottle of water is fine!)", "Look after the books, please. They have lots more adventures to go on with other readers.", "Bring them back on time, so your friends get a turn too.", "Happy reading!"],
    vocab: { incur: "cause yourself to have to pay or deal with something", permitted: "allowed" },
    questions: [["What is the only drink allowed?", ["water in a sealed bottle", "juice", "nothing at all"], 0, "retrieval"], ["What is the charge for late items?", ["10p per day", "£1 per week", "nothing"], 0, "retrieval"], ["Who is Version 2 written for?", ["children", "adult visitors", "library staff"], 0, "retrieval"], ["How does Version 2 explain why books must be returned on time?", ["so that friends get a turn too", "to avoid a fine", "because the library closes"], 0, "retrieval"], ["How are the two versions different?", ["Version 1 is formal and impersonal; Version 2 is friendly and chatty.", "They have different rules.", "Version 2 is more formal."], 0, "language"]],
    grammar: Object.assign({}, ESUBJ, { spots: ["It is requested that mobile phones be switched to silent and that conversations be kept to a minimum."],
      practice: [["Which phrase from Version 1 uses the subjunctive?", ["that mobile phones be switched to silent", "Food and drink are not permitted", "Hello, book explorers!"], 0], ["Rewrite informally: \"Food is not permitted.\"", ["No snacks, please!", "Food shall not be consumed.", "It is requested that food be not eaten."], 0], ["Why does Version 1 use the subjunctive?", ["to sound formal and official", "to sound friendly", "to tell a story"], 0]] }) },
  { id: "em18-plastic", band: 18, title: "Should Schools Ban Mobile Phones?", type: "Discussion", text: ["Few issues divide parents, pupils and teachers as sharply as whether mobile phones should be allowed in schools.", "Those who support a ban argue that phones are a constant distraction. Studies suggest that pupils who use their phones during lessons tend to remember less of what they have been taught. Supporters also point out that phones can make bullying easier, since unkind messages and photographs can spread across a whole school within minutes. Some schools that have introduced bans report that pupils are more focused in lessons and more sociable at break times.", "On the other hand, opponents of a ban insist that phones can be valuable learning tools, allowing pupils to research, record and create. Many parents, moreover, feel reassured knowing that their children can contact them on the journey to and from school. Banning phones entirely, they argue, does not teach young people how to use technology responsibly, which is a skill they will need for the rest of their lives.", "Perhaps the answer lies somewhere in between. Some schools allow phones to be brought in but require that they be handed in at the start of the day and collected at the end. Whatever the solution, it seems clear that the debate is unlikely to disappear any time soon."],
    vocab: { sociable: "friendly and enjoying the company of others", opponents: "people who disagree with an idea", reassured: "made to feel less worried" },
    questions: [["Give one argument for banning phones.", ["They are a distraction in lessons.", "They help with research.", "Parents can contact children."], 0, "retrieval"], ["Give one argument against banning phones.", ["Phones can be valuable learning tools.", "Phones make bullying easier.", "Pupils remember less."], 0, "retrieval"], ["What compromise do some schools use?", ["Phones are handed in at the start of the day and collected at the end.", "Phones are only allowed at lunch.", "Phones are banned for teachers too."], 0, "retrieval"], ["What tone does the writer use?", ["balanced and neutral", "strongly in favour of a ban", "strongly against a ban"], 0, "language"], ["How is the text organised?", ["introduction, arguments for, arguments against, conclusion", "a story in time order", "a list of instructions"], 0, "structure"]],
    grammar: Object.assign({}, EREG, { spots: ["Few issues divide parents, pupils and teachers as sharply", "Those who support a ban argue", "Studies suggest", "On the other hand, opponents of a ban insist", "moreover", "Perhaps the answer lies somewhere in between.", "it seems clear that"], practice: eregP }) },
  { id: "em18-grandad", band: 18, title: "My Grandad Says", type: "Poem", text: ["My grandad says that in his day", "they walked to school through snow and hay,", "that sweets cost just a penny each,", "that summers lasted from June to September", "and nobody ever forgot to remember", "to say please and thank you, or wipe their feet.", "My grandad says, if he were king,", "he'd ban the phone and the television screen,", "he'd make us all go out and play", "until the streetlamps lit the way.", "My grandad says a lot of things.", "I don't believe them all.", "But when he talks, his eyes go bright,", "as if he's ten years old tonight,", "and I'd rather hear him tell them wrong", "than not hear him at all."],
    vocab: { "in his day": "when he was young" },
    questions: [["What did sweets cost in Grandad's day, according to him?", ["a penny each", "nothing", "a pound"], 0, "retrieval"], ["What would Grandad do if he were king?", ["ban phones and television", "build more schools", "make sweets free"], 0, "retrieval"], ["Does the speaker believe everything Grandad says?", ["No, but loves hearing him anyway.", "Yes, completely.", "No, and finds him boring."], 0, "inference"], ["What does \"his eyes go bright, as if he's ten years old tonight\" suggest?", ["Grandad comes alive with happiness when he remembers his childhood.", "Grandad is tired.", "Grandad is ill."], 0, "language"], ["What is the tone of the final two lines?", ["affectionate and tender", "angry", "sarcastic"], 0, "language"]],
    grammar: Object.assign({}, ESUBJ, { spots: ["if he were king", "I'd rather hear him tell them wrong"], practice: esubjP }) },
  { id: "em18-bridge", band: 18, title: "The Bridge Builders", type: "Poem", text: ["They came with ropes and timber,", "when the river was in flood,", "and though the bank was crumbling", "and their boots were thick with mud,", "they worked until the morning,", "because a village waited there", "whose children needed schooling", "and whose sick needed care.", "They never saw it finished,", "for the work was slow and long,", "but the bridge that they began", "is standing still, and strong;", "and every child who crosses", "on the way to school today", "walks across a promise", "that was made and kept that day."],
    vocab: { timber: "wood used for building" },
    questions: [["What did the builders bring?", ["ropes and timber", "bricks and stone", "boats"], 0, "retrieval"], ["Why did they keep working until morning?", ["because a village was waiting for the bridge", "because they were paid more", "because it was too dark to go home"], 0, "retrieval"], ["Did the first builders see the bridge finished?", ["No, the work was too slow and long.", "Yes, the next day.", "Yes, after a week."], 0, "retrieval"], ["What does \"walks across a promise\" mean?", ["The bridge itself is the promise the builders kept.", "The children make promises.", "The bridge is made of paper."], 0, "language"], ["What is the tone of the poem?", ["admiring and grateful", "humorous", "angry"], 0, "language"]],
    grammar: Object.assign({}, ECOMP, { spots: ["when the river was in flood,", "and though the bank was crumbling", "because a village waited there", "whose children needed schooling", "and whose sick needed care.", "that was made and kept that day."], practice: ecompP }) }
];
TEST_A[18] = EMERALD_A; TEST_B[18] = EMERALD_B; TEXTS.push(...EMERALD_TEXTS);

/* =================== RUBY BAND: full set =================== */
/* RUBY BAND (19) · Stretch · reading age 13y6m–14y6m
   Grammar: cohesion across longer texts; rhetorical devices */
const RUBY_A = [
  ["Though the minister's speech was ___, it contained few concrete proposals.", ["eloquent", "elusive", "eminent", "elated"], 0], ["The Victorian narrator's ___ style can seem long-winded to modern readers.", ["verbose", "vigilant", "volatile", "venerable"], 0],
  ["Her refusal to compromise was seen by some as principled and by others as ___.", ["obstinate", "obsolete", "obscure", "oblivious"], 0], ["The scientist cautioned that the results, while ___, required further checks.", ["promising", "prohibitive", "provincial", "profane"], 0],
  ["The campaigners' ___ appeal persuaded thousands to sign the petition.", ["impassioned", "impassive", "impartial", "imperfect"], 0], ["The historian's account is widely regarded as the most ___ yet published.", ["authoritative", "authoritarian", "autobiographical", "automatic"], 0],
  ["The ___ of the argument rests on a single, disputed statistic.", ["crux", "crust", "crutch", "crest"], 0], ["The diplomat chose her words with great ___.", ["circumspection", "circumference", "circulation", "circumstance"], 0],
  ["The essay's conclusion ___ the points made earlier.", ["synthesises", "synchronises", "symbolises", "sympathises"], 0], ["The witness's testimony was ___ by the CCTV footage.", ["contradicted", "contracted", "contributed", "conducted"], 0],
  ["The novelist's ___ descriptions bring the Victorian city vividly to life.", ["evocative", "evasive", "evolutionary", "evaporative"], 0], ["Many readers find the poem's meaning ___ at first.", ["elusive", "illusive", "allusive", "exclusive"], 0],
  ["The speaker paused for ___ effect before revealing the result.", ["dramatic", "democratic", "diplomatic", "dramatised"], 0], ["The council's plan was ___ criticised in the local press.", ["roundly", "roughly", "rarely", "readily"], 0],
  ["The reforms were introduced ___, over a period of ten years.", ["gradually", "gratefully", "graciously", "grandly"], 0], ["The orator used ___ questions to engage the audience.", ["rhetorical", "rhythmical", "rheumatic", "romantic"], 0],
  ["The two scientists' theories are not ___; both could be correct.", ["mutually exclusive", "mutually agreeable", "mutinously exclusive", "musically exclusive"], 0], ["The charity's report painted a ___ picture of conditions in the camps.", ["bleak", "bleached", "blank", "bloated"], 0],
  ["The archaeologists worked ___ to uncover the mosaic.", ["painstakingly", "painfully", "painlessly", "paintingly"], 0], ["The film's message is ___, but never preachy.", ["powerful", "powerless", "powdery", "pointless"], 0],
  ["The proposal was ___ rejected by the committee.", ["unanimously", "anonymously", "unanimated", "unaccountably"], 0], ["The author ___ between past and present throughout the novel.", ["alternates", "alienates", "alleviates", "altercates"], 0],
  ["The detective's theory was ___ but lacked proof.", ["plausible", "palpable", "pliable", "plentiful"], 0], ["Her speech ended with a ___ call to action.", ["rousing", "rusting", "rinsing", "rotting"], 0],
  ["The essay considers the ___ of social media on young people.", ["impact", "impart", "impasse", "impound"], 0], ["The play explores the ___ between ambition and loyalty.", ["tension", "tenure", "tendon", "tenant"], 0],
  ["Several ___ of the rainforest have been cleared for farming.", ["swathes", "swatches", "swallows", "sweaters"], 0], ["Her arguments were ___ and well supported by evidence.", ["cogent", "cognate", "covert", "covetous"], 0],
  ["The author ___ the reader directly in the final chapter.", ["addresses", "adheres", "adjusts", "admires"], 0], ["The ___ of the novel is a small fishing village in Cornwall.", ["setting", "sitting", "settling", "settee"], 0]
];
const RUBY_B = [
  { title: "Why We Should Protect Our Oceans", text: ["Imagine a world without whales. Imagine beaches with no shells, rock pools with no crabs and seas with no fish. It sounds impossible. Yet scientists warn that, unless we act now, this is the future we are creating.", "Every year, eight million tonnes of plastic enter the oceans. That is the equivalent of a rubbish lorry emptying its load into the sea every single minute. This plastic does not disappear; instead, it breaks into smaller and smaller pieces, which are eaten by fish, and then, eventually, by us.", "Overfishing is a second threat. Huge industrial ships, some the size of football pitches, can catch hundreds of tonnes of fish in a single day. As a result, many species are being caught faster than they can reproduce.", "But there is hope. Where marine reserves have been created, fish populations have recovered remarkably quickly, sometimes within a few years. Where communities have cleaned their beaches, wildlife has returned.", "The ocean gives us food, oxygen and wonder. Surely it is time we gave something back?"],
    q: [["How much plastic enters the oceans every year?", ["eight million tonnes", "eight tonnes", "eight hundred tonnes"], 0, "retrieval"], ["What happens to plastic in the sea?", ["It breaks into smaller pieces that are eaten by fish.", "It disappears.", "It sinks and stays whole."], 0, "retrieval"], ["What has happened where marine reserves were created?", ["Fish populations recovered.", "Fishing increased.", "Plastic increased."], 0, "retrieval"], ["Why does the writer repeat \"Imagine\"?", ["to make the reader picture the loss and feel concerned", "to tell a fairy tale", "to give instructions"], 0, "language"], ["What is the effect of ending with a question?", ["It challenges the reader to act.", "It shows the writer is unsure.", "It starts a new topic."], 0, "structure"]] },
  { title: "The Lamplighter", text: ["Every evening, as the light faded over the cobbled streets of the old town, Mr Pell set out with his ladder and his long brass pole. He had lit the town's gas lamps for forty years, and his father had lit them before him.", "The townspeople barely noticed him. Children ran past him on their way home; shopkeepers pulled down their shutters; carriages rattled by. Yet without the old man, the streets would have sunk into darkness.", "Then, one autumn, the council announced that electric lights would replace the gas lamps. The new lights would switch themselves on. No lamplighter would be needed.", "On his final evening, Mr Pell walked his route as usual. But this time, he was not alone. Word had spread. At every lamp, someone was waiting: the baker, the schoolmistress, the children who had once run past him without a glance. As each lamp flickered into life, they clapped.", "By the time he reached the last lamp, the whole town was behind him. He climbed the ladder, lit the flame and, for a long moment, simply looked at it. Then he climbed down, and the crowd, which had been so noisy, fell silent."],
    q: [["How long had Mr Pell lit the lamps?", ["forty years", "four years", "one year"], 0, "retrieval"], ["Why was his job ending?", ["Electric lights were replacing the gas lamps.", "He was ill.", "The town was closing."], 0, "retrieval"], ["How did the townspeople treat him at the start?", ["They barely noticed him.", "They celebrated him every day.", "They were rude to him."], 0, "inference"], ["What changed on his final evening?", ["People waited at every lamp and clapped.", "It rained.", "He forgot his ladder."], 0, "retrieval"], ["Why does the crowd fall silent at the end?", ["They understand how much the moment means to him.", "They are bored.", "The lamp went out."], 0, "inference"]] },
  { title: "I Have a Question", text: ["Who painted the sky this morning", "in pink and gold and grey?", "Who taught the swift to sleep on the wing", "and the moon to find its way?", "Who wrote the song the blackbird sings", "at the edge of every day?", "And who decided, long ago,", "that rivers should not stay,", "but run, and run, and run, and run,", "and never once delay?", "I do not know. I may never know.", "But I'll keep asking anyway."],
    q: [["What colours was the sky this morning?", ["pink and gold and grey", "blue and white", "red and black"], 0, "retrieval"], ["What is unusual about how swifts sleep, according to the poem?", ["They sleep on the wing.", "They sleep underwater.", "They never sleep."], 0, "retrieval"], ["What effect does repeating \"run\" have?", ["It suggests the endless movement of rivers.", "It describes people running.", "It makes the poem stop."], 0, "language"], ["Why is the poem built from questions?", ["to show wonder and curiosity about nature", "because the poet is confused about maths", "to test the reader"], 0, "structure"], ["What does the poet decide at the end?", ["to keep asking even without answers", "to stop asking", "to find all the answers"], 0, "inference"]] }
];
const RCOH = { focus: "Cohesion across a longer text", explain: "Cohesion is how a text holds together. Writers link ideas across paragraphs with adverbials (however, as a result, meanwhile), pronouns and synonyms that refer back, repeated key words, and ellipsis (leaving out words the reader can work out)." };
const RRHET = { focus: "Rhetorical devices", explain: "Rhetorical devices are techniques that persuade or move an audience: rhetorical questions, the rule of three, repetition, direct address (you, we), contrast and emotive language." };
const rcohP = [["Which adverbial shows a result?", ["As a result", "Meanwhile", "For example"], 0], ["In \"The whale surfaced. The giant creature breathed out.\", what does \"The giant creature\" refer to?", ["the whale", "a new animal", "the sea"], 0], ["Which adverbial introduces a contrast?", ["However", "Furthermore", "Firstly"], 0]];
const rrhetP = [["Which is a rhetorical question?", ["Surely it is time we gave something back?", "What time is it?", "Where is the library?"], 0], ["Which uses the rule of three?", ["The ocean gives us food, oxygen and wonder.", "The ocean is big.", "The ocean gives us food."], 0], ["Which is an example of direct address?", ["You can make a difference.", "Whales are mammals.", "The sea is salty."], 0]];
const RUBY_TEXTS = [
  { id: "ru19-plague", band: 19, title: "The Village That Saved a Country", type: "Information", text: ["In the summer of 1665, a bundle of cloth arrived from London at the house of a tailor in the Derbyshire village of Eyam. The cloth was damp, so his assistant, George Viccars, hung it by the fire to dry. Within a week, Viccars was dead. The plague had come to Eyam.", "At that time, nobody understood how the disease spread. What people did know, however, was that it moved with travellers, and that a village which fled might carry it to towns and cities across the north of England.", "The village's young rector, William Mompesson, together with the former rector, Thomas Stanley, persuaded the villagers to do something extraordinary. They would quarantine themselves. Nobody would leave; nobody would enter. Food and supplies were left at boundary stones, where the villagers placed coins in holes filled with vinegar, which they believed would clean them.", "The cost was terrible. Over fourteen months, around 260 villagers died, among them Mompesson's own wife, Catherine. Some families lost every member.", "Yet the sacrifice worked. The plague did not spread beyond Eyam. Today, more than 350 years later, the village still remembers its dead every August, and the boundary stones can still be seen."],
    vocab: { rector: "a priest in charge of a church", quarantine: "keeping people apart to stop a disease spreading", boundary: "a line marking the edge of an area" },
    questions: [["How did the plague arrive in Eyam?", ["in a bundle of cloth from London", "on a ship", "with a traveller from France"], 0, "retrieval"], ["Why did the villagers decide not to leave?", ["to stop the plague spreading to other towns", "because the roads were closed", "because they were not allowed"], 0, "retrieval"], ["How did the villagers pay for supplies?", ["They left coins in holes filled with vinegar.", "They traded cloth.", "They didn't pay."], 0, "retrieval"], ["How does the word \"Yet\" in the last paragraph link back to the paragraph before?", ["It contrasts the terrible cost with the success of the plan.", "It adds another death.", "It begins a new story."], 0, "structure"], ["What word best describes the villagers' decision?", ["selfless", "careless", "selfish"], 0, "inference"]],
    grammar: Object.assign({}, RCOH, { spots: ["Within a week,", "The plague had come to Eyam.", "At that time,", "however,", "The village's young rector", "They would quarantine themselves.", "The cost was terrible.", "Yet the sacrifice worked.", "Today, more than 350 years later,"], practice: rcohP }) },
  { id: "ru19-speech", band: 19, title: "Speech: Every Child Deserves a Book", type: "Speech", text: ["Friends, colleagues, fellow readers: thank you for coming.", "Let me begin with a question. When did you last lose yourself in a book? When did a story last make you laugh out loud, or hold your breath, or cry?", "For many of us, those moments began in childhood. They began with a bedtime story, a library card, a dog-eared paperback passed from hand to hand. And yet, in our country today, one child in eight does not own a single book of their own. One in eight. Think about that.", "Reading is not a luxury. It is not a hobby for the lucky few. It is the key that unlocks every other subject: science, history, mathematics. Children who read for pleasure do better at school, regardless of their background. They are more confident, more creative and more able to understand the feelings of others.", "So what can we do? We can donate books. We can volunteer to read with children. We can campaign for every school to have a library and a librarian.", "We cannot give every child a perfect life. But we can give every child a book. And a book, as every reader in this room knows, can change everything."],
    vocab: { "dog-eared": "with corners of the pages folded and worn from use", luxury: "something pleasant but not necessary", campaign: "work in an organised way to achieve something" },
    questions: [["How many children do not own a book, according to the speech?", ["one in eight", "one in two", "one in a hundred"], 0, "retrieval"], ["What does the speaker say reading is the key to?", ["every other subject", "a good job only", "making friends"], 0, "retrieval"], ["Give one action the speaker suggests.", ["donate books", "buy a computer", "watch more films"], 0, "retrieval"], ["Why does the speaker repeat \"One in eight\"?", ["to emphasise the shocking statistic", "because she made a mistake", "to fill time"], 0, "language"], ["What is the effect of the final sentence?", ["It ends on a powerful, hopeful message.", "It changes the subject.", "It introduces a new speaker."], 0, "structure"]],
    grammar: Object.assign({}, RRHET, { spots: ["When did you last lose yourself in a book?", "make you laugh out loud, or hold your breath, or cry", "One in eight. Think about that.", "Reading is not a luxury. It is not a hobby for the lucky few.", "more confident, more creative and more able", "So what can we do?", "We can donate books. We can volunteer to read with children. We can campaign"], practice: rrhetP }) },
  { id: "ru19-twins", band: 19, title: "The Lighthouse Twins", type: "Story", text: ["Ada and Elsie Marsh were twins, but nobody who knew them would have said they were alike. Ada was loud; Elsie was quiet. Ada loved the town; Elsie loved the sea. Ada wanted to leave the island the moment she turned sixteen. Elsie wanted never to leave at all.", "Their father kept the lighthouse on Gannet Point. Every night, he climbed its hundred and twelve steps to light the lamp, and every night, Elsie went with him. Ada stayed below, reading magazines about London.", "Then, in the winter the twins turned fifteen, their father fell ill. The doctor came across from the mainland, shook his head and said he must rest for a month at least.", "That night, a storm blew in from the west. Elsie climbed the steps alone, but at the top she found that the mechanism which turned the great lens had jammed. Without it, the light would not flash, and ships would not know where the rocks were.", "She could not fix it on her own. She needed someone to turn the handle by hand while she cleared the jam. So, for the first time in years, she called down the stairs to her sister.", "Ada came. All night, the two of them worked side by side, taking turns at the handle until their arms ached. Neither of them said much. Neither of them needed to.", "When dawn came, the storm had passed and the ships were safe. And the sisters, for the first time, understood each other."],
    vocab: { mechanism: "the working parts of a machine", jammed: "stuck and unable to move", mainland: "the main area of land, not the island" },
    questions: [["How were Ada and Elsie different?", ["Ada was loud and loved the town; Elsie was quiet and loved the sea.", "They were exactly the same.", "Ada was older."], 0, "retrieval"], ["What was wrong with the lighthouse?", ["The mechanism that turned the lens had jammed.", "The lamp had no fuel.", "The steps had collapsed."], 0, "retrieval"], ["Why did Elsie need Ada?", ["Someone had to turn the handle while she cleared the jam.", "She was scared of the dark.", "She was ill."], 0, "retrieval"], ["How does the writer use contrast in the first paragraph?", ["by repeating the structure \"Ada was…; Elsie was…\"", "by describing the weather", "by using dialogue"], 0, "language"], ["What changes between the sisters by the end?", ["They understand each other for the first time.", "They argue more.", "Ada leaves the island."], 0, "summarising"]],
    grammar: Object.assign({}, RCOH, { spots: ["Ada was loud; Elsie was quiet.", "Ada loved the town; Elsie loved the sea.", "Then, in the winter the twins turned fifteen,", "That night,", "So, for the first time in years,", "Ada came.", "Neither of them said much. Neither of them needed to.", "When dawn came,", "And the sisters, for the first time,"], practice: rcohP }) },
  { id: "ru19-bees", band: 19, title: "Without Bees, What Then?", type: "Persuasive", text: ["What did you eat for breakfast this morning? An apple, perhaps? A spoonful of honey? A glass of orange juice? If so, you have bees to thank.", "Bees pollinate around a third of the food we eat. Without them, our supermarket shelves would look very different: no strawberries, no almonds, no tomatoes, no chocolate. The list goes on.", "Yet bee populations are in serious decline. Pesticides poison them. Disease weakens them. The loss of wild flowers starves them. In some parts of the world, farmers have already been forced to pollinate their fruit trees by hand, using tiny paintbrushes, a task that is slow, expensive and exhausting.", "Is this really the future we want?", "The good news is that every one of us can help. You do not need to be a scientist or a farmer. You need only a window box, a garden or a patch of grass that you are willing to let grow wild. Plant lavender. Plant foxgloves. Plant sunflowers. Leave the dandelions alone.", "Bees have fed us for thousands of years. Now, for once, it is our turn to feed them."],
    vocab: { pollinate: "carry pollen from flower to flower so plants make seeds and fruit", decline: "becoming fewer or weaker" },
    questions: [["How much of our food do bees pollinate?", ["around a third", "all of it", "a tiny amount"], 0, "retrieval"], ["Name one cause of bee decline.", ["pesticides", "too much rain", "honey farming"], 0, "retrieval"], ["What do some farmers already have to do?", ["pollinate trees by hand with paintbrushes", "import bees from space", "stop growing fruit"], 0, "retrieval"], ["Why does the writer begin with questions about breakfast?", ["to make the topic personal and relevant to the reader", "to talk about cooking", "to test the reader's memory"], 0, "language"], ["What is the effect of the final sentence?", ["It reverses the relationship, suggesting we owe bees something.", "It describes bees' food.", "It asks a question."], 0, "language"]],
    grammar: Object.assign({}, RRHET, { spots: ["What did you eat for breakfast this morning?", "no strawberries, no almonds, no tomatoes, no chocolate", "Pesticides poison them. Disease weakens them. The loss of wild flowers starves them.", "slow, expensive and exhausting", "Is this really the future we want?", "Plant lavender. Plant foxgloves. Plant sunflowers.", "Now, for once, it is our turn to feed them."], practice: rrhetP }) },
  { id: "ru19-ada", band: 19, title: "Ada Lovelace: The First Programmer", type: "Biography", text: ["In 1843, almost a hundred years before the first electronic computer was built, a young woman wrote what many historians consider to be the world's first computer program.", "Her name was Ada Lovelace. She was the daughter of the famous poet Lord Byron, although she never knew him; her parents separated when she was a baby. Her mother, determined that Ada should not become a poet like her father, insisted that she study mathematics and science instead.", "This decision would prove remarkable. At seventeen, Ada met the inventor Charles Babbage, who was designing a machine he called the Analytical Engine. The machine, which was never completed, was intended to carry out calculations automatically. Most people who saw Babbage's designs regarded the machine simply as a powerful calculator. Ada saw something more.", "In her notes on the machine, she described a step-by-step method by which it could calculate a complex sequence of numbers. More strikingly, she suggested that such a machine might one day create music or pictures, if those could be expressed in symbols.", "She was, in other words, imagining the modern computer.", "Ada died at only thirty-six. For many years, her work was overlooked. Today, however, a programming language bears her name, and the second Tuesday of October is celebrated as Ada Lovelace Day."],
    vocab: { "Analytical Engine": "a mechanical computer designed by Charles Babbage", sequence: "a set of things in a particular order", overlooked: "not noticed or valued" },
    questions: [["What did Ada write in 1843?", ["what many consider the first computer program", "a book of poems", "a novel"], 0, "retrieval"], ["Why did Ada's mother make her study mathematics?", ["so she would not become a poet like her father", "because Ada asked to", "to become a teacher"], 0, "retrieval"], ["How did Ada see the Analytical Engine differently from most people?", ["She imagined it could do much more than calculate, such as create music.", "She thought it was useless.", "She thought it was a toy."], 0, "inference"], ["How does the sentence \"She was, in other words, imagining the modern computer.\" help the reader?", ["It sums up the importance of the paragraph before.", "It starts a new topic.", "It gives a date."], 0, "structure"], ["How is Ada remembered today?", ["A programming language and a special day are named after her.", "She is forgotten.", "Only poets remember her."], 0, "retrieval"]],
    grammar: Object.assign({}, RCOH, { spots: ["Her name was Ada Lovelace.", "This decision would prove remarkable.", "The machine, which was never completed,", "Ada saw something more.", "More strikingly,", "She was, in other words, imagining the modern computer.", "Today, however,"], practice: rcohP }) },
  { id: "ru19-volcano", band: 19, title: "Pompeii: A City Frozen in Time", type: "Information", text: ["On the morning of 24th August, AD 79, the people of Pompeii went about their lives as usual. Bakers loaded their ovens. Traders opened their shops. Children played in the streets. Above them, the mountain they called Vesuvius stood quietly in the sunshine, its slopes covered in vineyards.", "Shortly after midday, it exploded.", "A column of ash and rock shot more than thirty kilometres into the sky. For hours, ash and pumice rained down on the city, collapsing roofs and filling the streets. Many people fled. Others, perhaps hoping the danger would pass, sheltered in their homes.", "Early the next morning, an avalanche of scorching gas and rock, travelling faster than a racing car, swept down the mountain and engulfed the city. Nobody who remained survived.", "Pompeii lay buried and forgotten for over 1,500 years. When archaeologists began to excavate it, they discovered something astonishing. The ash had preserved the city almost exactly as it had been on that final day: loaves of bread in ovens, graffiti on walls, even the shapes of people and animals, frozen in their last moments.", "Today, Pompeii offers us a unique window into ordinary Roman life, and a sobering reminder of the power of nature."],
    vocab: { pumice: "a light rock full of holes, formed from lava", engulfed: "completely covered or swallowed up", excavate: "dig carefully to uncover something buried" },
    questions: [["What was on the slopes of Vesuvius?", ["vineyards", "houses", "forests"], 0, "retrieval"], ["What happened to roofs during the first hours?", ["They collapsed under the weight of ash and pumice.", "They caught fire.", "They blew away."], 0, "retrieval"], ["Why might some people have stayed in their homes?", ["They hoped the danger would pass.", "They didn't notice.", "They were told to stay."], 0, "inference"], ["What is the effect of the one-sentence paragraph \"Shortly after midday, it exploded.\"?", ["It creates a sudden, dramatic turning point.", "It gives background information.", "It ends the text."], 0, "structure"], ["Why is Pompeii important to historians?", ["It preserves ordinary Roman life almost exactly.", "It is the oldest city.", "It is still active."], 0, "summarising"]],
    grammar: Object.assign({}, RCOH, { spots: ["On the morning of 24th August, AD 79,", "Shortly after midday, it exploded.", "For hours,", "Many people fled. Others,", "Early the next morning,", "Pompeii lay buried and forgotten for over 1,500 years.", "Today,"], practice: rcohP }) },
  { id: "ru19-letter", band: 19, title: "An Open Letter to Adults", type: "Letter", text: ["Dear grown-ups,", "You tell us that we are the future. You tell us that one day, the world will be ours. Well, we have been listening, and we have a question: what kind of world will you leave us?", "We have learned about melting ice caps in geography. We have learned about plastic in the oceans in science. We have learned about forests disappearing in our reading lessons. We are ten and eleven years old, and already we know more about the dangers facing our planet than many people knew in a lifetime.", "We are not asking you to be perfect. We are asking you to try. Walk instead of driving when you can. Turn off the lights. Mend things instead of throwing them away. Vote for people who will protect the places we love.", "We are doing our part. We pick up litter on our school field. We grow vegetables in our garden. We remind our families to recycle, sometimes more often than they would like.", "But we cannot do it alone. We need you.", "You say we are the future. Then please, help us to have one.", "Yours hopefully,", "Class 6R"],
    vocab: { "ice caps": "large areas of permanent ice at the North and South Poles" },
    questions: [["Who wrote the letter?", ["Class 6R", "a scientist", "a politician"], 0, "retrieval"], ["What subjects taught the children about the planet?", ["geography, science and reading", "maths and music", "PE and art"], 0, "retrieval"], ["What are the children doing to help?", ["picking up litter and growing vegetables", "nothing", "building houses"], 0, "retrieval"], ["How does the ending link back to the opening?", ["It returns to the idea that children are the future.", "It introduces a new topic.", "It repeats a fact about ice."], 0, "structure"], ["What is the tone of the letter?", ["respectful but urgent", "rude and angry", "light and jokey"], 0, "language"]],
    grammar: Object.assign({}, RRHET, { spots: ["You tell us that we are the future.", "what kind of world will you leave us?", "We have learned about melting ice caps in geography. We have learned about plastic in the oceans in science. We have learned about forests disappearing in our reading lessons.", "We are not asking you to be perfect. We are asking you to try.", "But we cannot do it alone. We need you.", "Then please, help us to have one."], practice: rrhetP }) },
  { id: "ru19-chess", band: 19, title: "The Chess Match", type: "Story", text: ["The hall was silent except for the tick of the clocks. Twenty boards, forty players, and only one game still going: the final of the under-twelves championship.", "Rahim had never played anyone like Sofia Novak. She had beaten him twice already this year, both times without seeming to try. Today, she sat perfectly still, her chin resting on her hand, her eyes half-closed, as though she were bored.", "He was not fooled. He had watched her games. He knew that stillness. It meant she was calculating, ten, twelve, fifteen moves ahead.", "For two hours, the game was balanced. Then, on the forty-first move, Rahim saw it: a sacrifice. If he gave up his queen, his most powerful piece, he could trap her king in three moves. But if he was wrong, he would lose everything.", "His hand hovered over the board. He thought of his grandfather, who had taught him the game on a cardboard board with bottle tops for pieces. He thought of the long evenings, the patient explanations, the words his grandfather always said: \"Fortune favours the brave, but only if they have done their homework.\"", "He moved the queen.", "Sofia opened her eyes. For the first time, she looked surprised. She studied the board for a long time. Then she smiled, tipped over her king and held out her hand.", "\"Well played,\" she said."],
    vocab: { sacrifice: "in chess, giving up a piece on purpose to gain an advantage", calculating: "working something out carefully", hovered: "stayed in the air just above something" },
    questions: [["What competition was this?", ["the under-twelves chess championship final", "a school quiz", "a football final"], 0, "retrieval"], ["What did Sofia's stillness really mean?", ["She was calculating many moves ahead.", "She was bored.", "She was asleep."], 0, "inference"], ["What risk did Rahim take?", ["He sacrificed his queen.", "He resigned.", "He moved his king."], 0, "retrieval"], ["What does his grandfather's saying mean?", ["Taking risks pays off if you have prepared properly.", "Always be brave, whatever happens.", "Homework is more important than chess."], 0, "inference"], ["What does Sofia's reaction at the end show about her?", ["She is a gracious and sporting player.", "She is angry.", "She does not care about chess."], 0, "inference"]],
    grammar: Object.assign({}, RCOH, { spots: ["He was not fooled.", "He knew that stillness.", "For two hours,", "Then, on the forty-first move,", "But if he was wrong,", "He moved the queen.", "For the first time,", "Then she smiled,"], practice: rcohP }) },
  { id: "ru19-ifyou", band: 19, title: "If You Want to See the World", type: "Poem", text: ["If you want to see the world, go slowly.", "Go slowly past the hedge and the gate,", "past the old man feeding sparrows,", "past the cat that sits on the wall and waits.", "If you want to see the world, look closely.", "Look closely at the beetle's shine,", "the frost-lace on the window,", "the spider's silver line.", "If you want to see the world, ask questions.", "Ask why, and how, and where, and when.", "And when you think you've seen it all,", "go back and look again."],
    vocab: { "frost-lace": "delicate patterns of frost that look like lace" },
    questions: [["What does the poet say you should do first to see the world?", ["go slowly", "travel far", "take photographs"], 0, "retrieval"], ["What is the old man doing?", ["feeding sparrows", "walking a dog", "reading"], 0, "retrieval"], ["What is \"the spider's silver line\"?", ["a thread of spider's silk", "a road", "a river"], 0, "language"], ["How is the poem structured?", ["Each verse begins \"If you want to see the world\" with a new instruction.", "It tells a story in time order.", "It has no pattern."], 0, "structure"], ["What is the message of the last two lines?", ["There is always more to notice.", "You can see everything in one day.", "Looking is a waste of time."], 0, "inference"]],
    grammar: Object.assign({}, RRHET, { spots: ["If you want to see the world, go slowly.", "If you want to see the world, look closely.", "If you want to see the world, ask questions.", "Ask why, and how, and where, and when.", "go back and look again."], practice: rrhetP }) },
  { id: "ru19-tree", band: 19, title: "The Last Tree", type: "Poem", text: ["They cut the forest, tree by tree,", "to build the town, to cross the sea;", "they cut the oak, they cut the pine,", "they cut the ash in a long, straight line.", "And when the hills were brown and bare,", "the people stopped and stood and stared:", "one tree was left, one tree alone,", "its roots wrapped round a mossy stone.", "A child came up the hill at dawn", "with a bucket and a single acorn,", "and knelt, and dug, and planted it there.", "The forest begins again. Somewhere."],
    vocab: { bare: "empty, with nothing covering it" },
    questions: [["Why was the forest cut down?", ["to build the town and cross the sea", "because the trees were ill", "to make space for a school"], 0, "retrieval"], ["How many trees were left?", ["one", "none", "a hundred"], 0, "retrieval"], ["What does the child plant?", ["an acorn", "a pine tree", "flowers"], 0, "retrieval"], ["What is the effect of repeating \"they cut\"?", ["It emphasises how much was destroyed.", "It makes the poem funny.", "It describes the child."], 0, "language"], ["What is the tone at the end?", ["quietly hopeful", "angry", "hopeless"], 0, "language"]],
    grammar: Object.assign({}, RRHET, { spots: ["they cut the oak, they cut the pine,", "they cut the ash", "the people stopped and stood and stared", "one tree was left, one tree alone,", "and knelt, and dug, and planted it there.", "The forest begins again. Somewhere."], practice: rrhetP }) }
];
TEST_A[19] = RUBY_A; TEST_B[19] = RUBY_B; TEXTS.push(...RUBY_TEXTS);

/* =================== DIAMOND BAND: full set =================== */
/* DIAMOND BAND (20) · Stretch · reading age 14y6m–15y6m+
   Grammar: how writers combine grammar, vocabulary and structure — hedging and certainty; figurative language; building an argument */
const DIAMOND_A = [
  ["The essayist argues that progress is not ___ but depends on the choices of each generation.", ["inevitable", "ineffable", "inanimate", "incessant"], 0], ["The author's ___ use of irony lets her criticise society without appearing to do so.", ["subtle", "sullen", "servile", "sedate"], 0],
  ["The general's ___ retreat saved his army from certain defeat.", ["judicious", "ludicrous", "jocular", "gratuitous"], 0], ["The pamphlet was dismissed as mere ___, designed to provoke rather than inform.", ["polemic", "panacea", "paradigm", "pastiche"], 0],
  ["The evidence, though ___, is not yet conclusive.", ["suggestive", "suggested", "suggestible", "suggestion"], 0], ["The poet's imagery is ___, rich with colour and sound.", ["sensuous", "sensible", "sensitive", "sensational"], 0],
  ["Critics have long debated the ___ of the novel's final chapter.", ["significance", "signature", "signification", "signal"], 0], ["The scientist was careful not to ___ her conclusions beyond what the data showed.", ["overstate", "overtake", "overturn", "overhear"], 0],
  ["The narrator's ___ account leaves readers unsure what really happened.", ["unreliable", "unremarkable", "unrelenting", "unrelated"], 0], ["The treaty marked a ___ moment in the country's history.", ["pivotal", "pivoted", "pitiful", "pictorial"], 0],
  ["The city's ___ skyline glittered against the night.", ["jagged", "jaded", "jolly", "jumbled"], 0], ["His apology seemed ___, as though he did not really mean it.", ["perfunctory", "peremptory", "perpetual", "perplexing"], 0],
  ["The archaeologists' theory, while ___, has not been proved.", ["compelling", "compulsive", "competing", "complicit"], 0], ["The author ___ two timelines that finally meet in the last chapter.", ["interweaves", "interviews", "intervenes", "intercepts"], 0],
  ["The novel's tone shifts from ___ to despairing as the war progresses.", ["optimistic", "optical", "optional", "opportune"], 0], ["The debate was marked by ___ exchanges between the candidates.", ["acrimonious", "acrobatic", "accommodating", "acoustic"], 0],
  ["Researchers ___ that the decline may be linked to climate change.", ["hypothesise", "hypnotise", "hyphenate", "hydrate"], 0], ["The phrase \"a sea of troubles\" is an example of a ___.", ["metaphor", "simile", "pun", "palindrome"], 0],
  ["The essay's structure is ___: each paragraph builds on the last.", ["cumulative", "cumbersome", "cursory", "customary"], 0], ["Her ___ wit made her a popular guest.", ["sparkling", "sparing", "spurious", "sparse"], 0],
  ["The report's findings ___ earlier research.", ["corroborate", "corrugate", "correspond", "corrode"], 0], ["The landscape was ___, empty of any sign of life.", ["desolate", "desirable", "dissolute", "decorated"], 0],
  ["The leader's ___ promises were soon forgotten.", ["grandiose", "graceful", "gracious", "granular"], 0], ["The author ___ the reader's expectations with a surprising ending.", ["subverts", "subsides", "submits", "subscribes"], 0],
  ["Scientists remain ___ about the long-term effects.", ["uncertain", "unconcerned", "unconscious", "uncovered"], 0], ["The storm's ___ was felt across the entire coast.", ["ferocity", "fertility", "festivity", "frugality"], 0],
  ["The novel ___ themes of loss, memory and belonging.", ["explores", "explodes", "exploits", "expires"], 0], ["The speech was ___ with references to history.", ["laced", "lazed", "lacked", "lashed"], 0],
  ["The ___ of the poem echoes the rhythm of the sea.", ["cadence", "candour", "cadaver", "candle"], 0], ["The result was, ___, a triumph for the whole team.", ["arguably", "argumentatively", "arguing", "argued"], 0]
];
const DIAMOND_B = [
  { title: "The Glass Frog", text: ["In the cloud forests of Central and South America lives a creature so delicate that you can see straight through it. The glass frog, which is rarely longer than three centimetres, has skin on its underside that is almost entirely transparent. Turn one over, and you can watch its tiny heart beating.", "For years, scientists puzzled over a mystery. When a glass frog sleeps on a leaf during the day, its body appears to fade, as though it were vanishing. In 2022, researchers discovered why. While the frog rests, it removes almost all of the red blood cells from its blood and hides them, packed tightly, inside its liver. Without the red blood, light passes through its body, and the frog becomes nearly invisible to predators.", "Even more remarkably, the frog seems to suffer no harm from this. In most animals, packing blood cells together in this way would cause dangerous clots. How the glass frog avoids this remains unclear, but scientists suggest that understanding it could one day help to develop new medicines for people."],
    q: [["Where do glass frogs live?", ["in the cloud forests of Central and South America", "in deserts", "in the Arctic"], 0, "retrieval"], ["What can you see through a glass frog's skin?", ["its heart beating", "its bones only", "nothing"], 0, "retrieval"], ["How does the frog become nearly invisible?", ["It hides its red blood cells in its liver.", "It changes colour.", "It buries itself."], 0, "retrieval"], ["Why does the writer use \"seems\" and \"suggest\"?", ["because scientists are not yet certain", "to make it sound exciting", "because the writer is lying"], 0, "language"], ["Why might the frog's ability matter to people?", ["It could help develop new medicines.", "It could make people invisible.", "It could be used for food."], 0, "inference"]] },
  { title: "The Return", text: ["The village had shrunk. That was the first thing Leila noticed when the bus set her down at the crossroads, thirty years after she had left. The square, which in her memory stretched as wide as a field, was barely bigger than a playground. The fountain, once a roaring giant, trickled thinly into its stone basin. Even the mountains seemed to have stepped back.", "She walked slowly up the hill to her grandmother's house. The door, she saw, had been painted blue. Someone had planted geraniums along the wall. A child's bicycle lay on its side in the yard.", "For a long time, she stood at the gate. She had imagined this moment so often that now it had arrived, she did not know what to do with it.", "Then the door opened, and a small girl looked out at her with frank curiosity.", "\"Are you lost?\" asked the girl.", "Leila considered the question. \"No,\" she said at last, and found, to her surprise, that she was smiling. \"I think I've just been found.\""],
    q: [["How long had Leila been away?", ["thirty years", "three years", "thirteen years"], 0, "retrieval"], ["Why does the village seem to have \"shrunk\"?", ["Leila remembers it from when she was small.", "Buildings were knocked down.", "It was flooded."], 0, "inference"], ["What does \"the fountain, once a roaring giant\" show?", ["how impressive it seemed to her as a child", "that there was a giant in the village", "that the fountain was dangerous"], 0, "language"], ["How has the house changed?", ["The door is blue and someone lives there with a child.", "It has been knocked down.", "It is exactly the same."], 0, "retrieval"], ["What does Leila mean by \"I think I've just been found\"?", ["She feels she has come home and belongs again.", "She was lost on the bus.", "Someone was looking for her."], 0, "inference"]] },
  { title: "Ozymandias (an extract retold)", text: ["The poet Percy Bysshe Shelley, writing in 1818, imagined a traveller from an ancient land describing a ruined statue in the desert. Only two vast stone legs still stood. Nearby, half-buried in the sand, lay a shattered face, its lip curled in a cold sneer of command.", "On the base of the statue, words were carved. They boasted that this was Ozymandias, king of kings, and dared other mighty rulers to look upon his works and despair.", "Yet around the broken statue, Shelley tells us, nothing else remains. There is no city, no palace, no empire. There is only sand, stretching away, lone and level, in every direction.", "The irony is powerful. The king believed his power would last forever, and he wished others to be overwhelmed by it. Instead, time has destroyed everything he built. His boast now reads as a warning: no power, however great, lasts forever."],
    q: [["When did Shelley write the poem?", ["1818", "1918", "818"], 0, "retrieval"], ["What remained of the statue?", ["two stone legs and a shattered face", "a whole statue", "only the base"], 0, "retrieval"], ["What did the words on the base claim?", ["that Ozymandias was king of kings", "that the statue was a gift", "that the city was beautiful"], 0, "retrieval"], ["What is ironic about the inscription?", ["It boasts of great works, but nothing remains around it.", "It is written in the wrong language.", "It is funny."], 0, "inference"], ["What is the main message, according to the writer?", ["No power lasts forever.", "Statues should be repaired.", "Deserts are dangerous."], 0, "summarising"]] }
];
const DHEDGE = { focus: "Degrees of certainty", explain: "Careful writers show exactly how sure they are. Modal verbs (may, might, could, must), adverbs (perhaps, possibly, certainly, arguably) and verbs such as suggest, appear and seem let them present ideas as certain, likely or only possible." };
const DFIG = { focus: "Figurative language and imagery", explain: "Writers use metaphors, similes and personification to create vivid images and suggest feelings. A metaphor says one thing is another (the fountain was a roaring giant); personification gives human qualities to things (the mountains stepped back)." };
const DSTRUCT = { focus: "Building an argument", explain: "A strong argument is carefully structured: a clear opening position, topic sentences that start each paragraph, evidence, a counter-argument that is fairly answered, and a conclusion that returns to the main point." };
const dhedgeP = [["Which sentence is least certain?", ["The ruins might be Roman.", "The ruins are Roman.", "The ruins must be Roman."], 0], ["Which word shows the writer is only suggesting something?", ["perhaps", "definitely", "always"], 0], ["Why do scientists often use hedging?", ["to avoid claiming more than the evidence shows", "to confuse readers", "to sound informal"], 0]];
const dfigP = [["Which is a metaphor?", ["The classroom was a zoo.", "The classroom was like a zoo.", "The classroom was noisy."], 0], ["Which is personification?", ["The wind whispered through the trees.", "The wind was strong.", "The wind blew at 40 mph."], 0], ["What does \"a blanket of fog\" suggest?", ["thick fog covering everything", "a warm bed", "a light mist"], 0]];
const dstructP = [["What is a topic sentence?", ["a sentence that introduces the main idea of a paragraph", "the title", "the last sentence of the text"], 0], ["Why include a counter-argument?", ["to show the writer has considered other views and can answer them", "to confuse the reader", "to fill space"], 0], ["Which is a good conclusion phrase?", ["In conclusion, the evidence clearly shows", "Once upon a time", "Firstly"], 0]];
const DIAMOND_TEXTS = [
  { id: "di20-stonehenge", band: 20, title: "Who Built Stonehenge?", type: "Information", text: ["Stonehenge is perhaps the most famous prehistoric monument in Europe, yet, more than four thousand years after it was built, it remains surrounded by unanswered questions.", "What we do know is that it was constructed in stages over roughly 1,500 years, beginning around 3000 BC. The largest stones, known as sarsens, weigh up to twenty-five tonnes and were probably brought from about twenty-five kilometres away. The smaller bluestones, remarkably, appear to have come from the Preseli Hills in Wales, over 200 kilometres to the west.", "How these stones were moved is far less certain. Some archaeologists believe they were dragged on wooden sledges over log rollers; others have suggested that they may have been floated part of the way along rivers. Experiments have shown that a team of a few dozen people could, in principle, haul a large stone a kilometre or more in a day.", "Its purpose is even more debated. The monument is precisely aligned with the sunrise at the summer solstice and the sunset at the winter solstice, which strongly suggests that it had some connection with the calendar or with religious ceremonies. Human remains discovered nearby indicate that it may also have been a burial site.", "It is possible that we will never know the full answer. And perhaps that is part of its power."],
    vocab: { prehistoric: "from the time before written records", solstice: "the longest or shortest day of the year", aligned: "lined up with something" },
    questions: [["Over how long was Stonehenge built?", ["roughly 1,500 years", "one year", "fifty years"], 0, "retrieval"], ["Where did the bluestones probably come from?", ["the Preseli Hills in Wales", "London", "France"], 0, "retrieval"], ["What suggests Stonehenge was linked to the calendar?", ["It is aligned with the solstice sunrise and sunset.", "It has a clock.", "It was built in summer."], 0, "retrieval"], ["Why does the writer use words like \"probably\", \"may\" and \"suggests\"?", ["because much about Stonehenge is still uncertain", "to sound informal", "to tell a story"], 0, "language"], ["What does the final sentence suggest?", ["The mystery makes Stonehenge even more fascinating.", "Stonehenge is boring.", "Scientists have solved everything."], 0, "inference"]],
    grammar: Object.assign({}, DHEDGE, { spots: ["perhaps the most famous", "were probably brought", "remarkably, appear to have come", "Some archaeologists believe", "may have been floated", "could, in principle,", "strongly suggests", "indicate that it may also have been", "It is possible that", "perhaps that is part of its power"], practice: dhedgeP }) },
  { id: "di20-city", band: 20, title: "The City Wakes", type: "Description", text: ["The city does not wake all at once. It stirs, the way a great animal stirs, one limb at a time.", "First come the street sweepers, their brushes whispering along the gutters. Then the bakers, who have been awake for hours, roll up their shutters and release into the street the warm, golden breath of bread. A tram groans out of its depot and begins its long, rattling journey across the river, its windows still fogged with the cold of the night.", "By seven, the city has opened its eyes. Traffic lights blink from red to green, though there is nobody yet to obey them. Pigeons gather on the cathedral steps like elderly gentlemen waiting for a meeting that never begins. Somewhere a dog barks, and somewhere else another answers, and the conversation passes from street to street until it fades into the hum of engines.", "By eight, the city is wide awake, and roaring. Its arteries are clogged with buses and bicycles, its pavements are rivers of hurrying people, and its voice, made of a million voices, rises into the sky.", "And high above it all, on the roof of the tallest tower, a single gull stands perfectly still, watching, as if it alone remembers the quiet."],
    vocab: { depot: "a place where buses or trams are kept", arteries: "here, the main roads of a city (arteries carry blood in the body)", clogged: "blocked" },
    questions: [["Who are the first people to appear?", ["the street sweepers", "the bakers", "the tram drivers"], 0, "retrieval"], ["What is the city compared to in the first paragraph?", ["a great animal waking up", "a machine", "a river"], 0, "language"], ["What are the pigeons compared to?", ["elderly gentlemen waiting for a meeting", "soldiers", "children"], 0, "language"], ["How does the writer show time passing?", ["with times at the start of paragraphs: \"By seven\", \"By eight\"", "with dates", "by changing narrator"], 0, "structure"], ["What does the gull at the end suggest?", ["a stillness that contrasts with the noisy city", "that it is about to attack", "that it is lost"], 0, "inference"]],
    grammar: Object.assign({}, DFIG, { spots: ["It stirs, the way a great animal stirs, one limb at a time.", "their brushes whispering along the gutters", "the warm, golden breath of bread", "A tram groans out of its depot", "the city has opened its eyes", "like elderly gentlemen waiting for a meeting that never begins", "Its arteries are clogged with buses and bicycles", "its pavements are rivers of hurrying people", "as if it alone remembers the quiet"], practice: dfigP }) },
  { id: "di20-homework", band: 20, title: "Should Homework Be Abolished?", type: "Argument", text: ["Homework has been part of school life for over a century. Yet, increasingly, parents, teachers and researchers are asking whether it does more harm than good. In this essay, I will argue that, while homework should not be abolished altogether, it should be dramatically reduced for primary-aged children.", "The strongest argument against homework concerns its effect on family life and wellbeing. Children who spend their evenings on worksheets have less time to play, to read for pleasure, to be outdoors and to rest. Several studies suggest that, for children under eleven, large amounts of homework have little measurable effect on achievement, while they may increase stress.", "Supporters of homework argue, reasonably, that it teaches independence and helps pupils to practise what they have learned. This is a fair point. However, these benefits can be gained from small amounts of well-designed work, such as reading together or learning times tables, rather than hours of written tasks.", "A further concern is fairness. Children whose families have time, space and resources to help them are at a clear advantage; those without such support may fall further behind.", "In conclusion, the evidence suggests that homework for younger children should be short, purposeful and, wherever possible, enjoyable. Reading for pleasure, after all, may be the most valuable homework of all."],
    vocab: { abolished: "officially ended", wellbeing: "being healthy and happy", purposeful: "having a clear aim" },
    questions: [["What is the writer's main position?", ["Homework should be reduced, not abolished.", "Homework should be abolished completely.", "Homework should be increased."], 0, "summarising"], ["What does the second paragraph argue?", ["Too much homework harms family life and wellbeing.", "Homework improves achievement greatly.", "Homework is fun."], 0, "retrieval"], ["How does the writer respond to supporters of homework?", ["by accepting their point but saying the benefits come from small amounts of work", "by ignoring them", "by agreeing completely"], 0, "structure"], ["What is the fairness concern?", ["Children with more support at home are at an advantage.", "Teachers mark unfairly.", "Some children get more homework."], 0, "retrieval"], ["Why does the writer include the counter-argument?", ["to make the argument more balanced and convincing", "to change their mind", "to make it longer"], 0, "structure"]],
    grammar: Object.assign({}, DSTRUCT, { spots: ["In this essay, I will argue that", "The strongest argument against homework concerns", "Supporters of homework argue, reasonably,", "This is a fair point. However,", "A further concern is fairness.", "In conclusion, the evidence suggests that"], practice: dstructP }) },
  { id: "di20-ice", band: 20, title: "Voices from the Ice", type: "Information", text: ["Deep beneath the surface of Antarctica lies a record of Earth's history stretching back more than 800,000 years. It is written not in words, but in ice.", "Every year, snow falls on the Antarctic plateau and is slowly pressed down by the layers above it until it becomes solid ice. As it forms, it traps tiny bubbles of air. Those bubbles are, in effect, samples of the atmosphere as it was at the moment they were sealed.", "By drilling long cylinders of ice, called ice cores, scientists can travel back through time. The deeper they drill, the older the ice. By analysing the air in each layer, they can measure how much carbon dioxide the atmosphere contained, and, by studying the ice itself, they can estimate the temperature of the time.", "What the ice reveals is striking. Over hundreds of thousands of years, carbon dioxide and temperature have risen and fallen together. Yet in no layer, at any point in those 800,000 years, does the level of carbon dioxide come close to what it is today.", "Scientists are careful about what they claim, and the ice cannot predict the future. But it does tell us, very clearly, that the changes now taking place are unlike anything the Earth has experienced in a very long time."],
    vocab: { plateau: "a large, high, flat area of land", atmosphere: "the layer of gases around the Earth", cylinders: "tube shapes" },
    questions: [["How far back does the Antarctic ice record go?", ["more than 800,000 years", "800 years", "8,000 years"], 0, "retrieval"], ["What do the air bubbles in the ice contain?", ["samples of the atmosphere from long ago", "water", "fossils"], 0, "retrieval"], ["What is the link between the depth and the age of the ice?", ["The deeper the ice, the older it is.", "The deeper the ice, the younger it is.", "There is no link."], 0, "retrieval"], ["What does the ice reveal about carbon dioxide today?", ["It is far higher than at any point in 800,000 years.", "It is lower than ever.", "It is the same as always."], 0, "retrieval"], ["What is the effect of the metaphor \"It is written not in words, but in ice\"?", ["It presents the ice as a kind of history book.", "It describes snow falling.", "It explains how to drill."], 0, "language"]],
    grammar: Object.assign({}, DHEDGE, { spots: ["in effect,", "they can estimate", "Scientists are careful about what they claim", "the ice cannot predict the future", "very clearly,"], practice: dhedgeP }) },
  { id: "di20-violin", band: 20, title: "The Violin", type: "Story", text: ["The violin had belonged to Mira's great-grandmother, who had carried it across three borders in a suitcase lined with newspaper. Now it lay on the kitchen table, its varnish cracked like old paint on a door, its strings slack.", "\"It hasn't been played in fifty years,\" said Mira's father. \"I doubt it can be.\"", "Mira did not doubt. She took it to Mr Havel, the instrument maker whose shop smelled of wood shavings and glue, and who had hands that seemed too large and too gentle for such delicate work. He turned the violin over slowly, as though reading a letter.", "\"This,\" he said at last, \"has a story inside it. Leave it with me.\"", "For six weeks, Mira waited. When she returned, the violin had been transformed. Its body gleamed like a polished chestnut; its new strings shone. Mr Havel handed it to her without a word.", "She lifted the bow. The first note was thin and uncertain, a bird testing the air. The second was stronger. And then, quite suddenly, the instrument seemed to remember itself, and a sound poured out of it, rich and dark and full of longing, that filled the little shop to its rafters.", "Mr Havel closed his eyes. \"There,\" he said quietly. \"Now she is home.\""],
    vocab: { varnish: "a shiny protective coating on wood", slack: "loose, not tight", rafters: "the sloping beams that hold up a roof" },
    questions: [["How did the violin reach the family?", ["Mira's great-grandmother carried it across three borders.", "It was bought in a shop.", "It was a birthday present."], 0, "retrieval"], ["What did Mira's father think?", ["that the violin could not be played", "that it was valuable", "that Mira should sell it"], 0, "retrieval"], ["What does the simile \"as though reading a letter\" suggest about Mr Havel?", ["He examines the violin carefully, as if it has a message.", "He cannot read.", "He is bored."], 0, "language"], ["How does the writer show the violin \"coming back to life\"?", ["The notes grow from thin to strong to rich and full.", "It changes colour.", "It breaks."], 0, "structure"], ["What does \"Now she is home\" suggest?", ["The violin has found its rightful place and voice again.", "Mira is going home.", "Mr Havel is going home."], 0, "inference"]],
    grammar: Object.assign({}, DFIG, { spots: ["its varnish cracked like old paint on a door", "too large and too gentle for such delicate work", "as though reading a letter", "has a story inside it", "Its body gleamed like a polished chestnut", "a bird testing the air", "the instrument seemed to remember itself", "rich and dark and full of longing"], practice: dfigP }) },
  { id: "di20-ai", band: 20, title: "Can Machines Be Creative?", type: "Discussion", text: ["Computer programs can now write poems, compose music and paint pictures. Some of their work is impressive enough to fool experts. This raises a fascinating question: can a machine truly be creative?", "Those who answer yes point to the results. If a computer produces a painting that moves people, they argue, it seems unreasonable to deny that the painting is creative simply because a machine made it. After all, they say, human artists also learn by studying the work of others.", "Those who answer no, however, focus on the process. A computer, they argue, does not feel joy, grief or wonder. It does not choose to create; it follows instructions. Without intention or experience, they suggest, what it produces may resemble art, but it cannot be art in the fullest sense.", "There may be a middle way. Many artists now use computer programs as tools, much as earlier generations used cameras or synthesisers. In such cases, the creativity arguably lies in the partnership: in the human's choices about what to ask for, what to keep and what to throw away.", "The question is unlikely to be settled soon. But in asking it, we are forced to think more carefully about what creativity means, and about what makes human experience valuable."],
    vocab: { compose: "write music", intention: "a plan or purpose", synthesisers: "electronic instruments that create sounds" },
    questions: [["What can computer programs now do?", ["write poems, compose music and paint pictures", "only do maths", "feel emotions"], 0, "retrieval"], ["What do people who answer yes focus on?", ["the results", "the process", "the cost"], 0, "retrieval"], ["Why do people who answer no say a machine cannot be creative?", ["It has no feelings, intention or experience.", "It is too slow.", "It is too expensive."], 0, "retrieval"], ["What is the \"middle way\"?", ["seeing creativity in the partnership between human and machine", "banning computers", "letting machines decide"], 0, "inference"], ["Why does the writer use words like \"may\", \"arguably\" and \"suggest\"?", ["to present a balanced view without claiming certainty", "to sound informal", "because they are unsure what the topic is"], 0, "language"]],
    grammar: Object.assign({}, DSTRUCT, { spots: ["This raises a fascinating question:", "Those who answer yes point to the results.", "Those who answer no, however, focus on the process.", "There may be a middle way.", "The question is unlikely to be settled soon."], practice: dstructP }) },
  { id: "di20-diary", band: 20, title: "From the Diary of a Lighthouse Keeper, 1899", type: "Diary", text: ["14th December", "Wind from the north-east, strengthening through the afternoon. By four o'clock, the sea had risen to such a height that spray was striking the lantern room, some forty metres above the rock. I have kept this light for eleven years and have seldom seen its equal.", "15th December", "A wretched night. The tower shook at every wave, as though some great fist were beating upon the door. I did not sleep, but kept the lamp trimmed and the lens turning by hand, the clockwork having failed at around two. My arms are aching still.", "At first light, I saw, through the glass, a vessel in difficulty to the south: a small schooner, her mainsail torn, drifting towards the Mare's Teeth. I could do nothing but keep the light burning and pray that her master knew these waters.", "16th December", "The schooner is safe. A boat came out from the harbour this morning with the news that she had seen our light and turned in time. Her master sent word that he owed his crew's lives to the keeper of the light.", "I set this down not from pride, but because it is a comfort, on such lonely nights, to know that the light is seen."],
    vocab: { seldom: "rarely", wretched: "very unpleasant", schooner: "a type of sailing ship" },
    questions: [["How long had the writer kept the light?", ["eleven years", "eleven days", "forty years"], 0, "retrieval"], ["What failed during the night?", ["the clockwork that turned the lens", "the lamp", "the door"], 0, "retrieval"], ["What was the schooner drifting towards?", ["the Mare's Teeth", "the harbour", "the lighthouse"], 0, "retrieval"], ["What does the simile \"as though some great fist were beating upon the door\" suggest?", ["the violent force of the waves", "a visitor arriving", "a quiet night"], 0, "language"], ["Why does the keeper write about the rescue?", ["It comforts him to know the light is seen.", "He wants a reward.", "He is proud of himself."], 0, "inference"]],
    grammar: Object.assign({}, DFIG, { spots: ["as though some great fist were beating upon the door", "the Mare's Teeth", "on such lonely nights"], practice: dfigP }) },
  { id: "di20-language", band: 20, title: "Why Languages Disappear", type: "Information", text: ["There are around 7,000 languages spoken in the world today. By the end of this century, linguists estimate that as many as half of them could have disappeared.", "Languages die when people stop passing them on to their children. This usually happens gradually. A community may come under pressure to use a more powerful language, perhaps for work, for education or simply to be accepted. Parents, wanting the best for their children, may choose to speak to them in that language instead. Within two or three generations, the old language may be spoken only by a handful of elderly people. When the last of them dies, the language dies too.", "Why does this matter? Each language contains a unique way of seeing the world. Some languages have words for kinds of snow, or wind, or family relationships that have no equivalent anywhere else. Many hold detailed knowledge about local plants, animals and medicines that has never been written down. When a language disappears, that knowledge may vanish with it.", "Fortunately, languages can also be revived. Hebrew, which for centuries was used mainly for prayer and study, is now spoken every day by millions of people. Welsh, once in steep decline, is now taught in every school in Wales.", "The future of the world's languages, then, is not yet decided. It depends, to a large extent, on the choices we make."],
    vocab: { linguists: "people who study languages", equivalent: "something that has the same meaning or value", revived: "brought back to life or use" },
    questions: [["How many languages are spoken in the world today?", ["around 7,000", "around 700", "around 70,000"], 0, "retrieval"], ["Why do languages usually die?", ["People stop passing them on to their children.", "Governments ban them.", "They become too difficult."], 0, "retrieval"], ["What knowledge might be lost with a language?", ["knowledge about local plants, animals and medicines", "maths", "how to read"], 0, "retrieval"], ["Which two languages are given as examples of revival?", ["Hebrew and Welsh", "English and French", "Arabic and Chinese"], 0, "retrieval"], ["What does the final paragraph suggest?", ["Our choices can still save languages.", "All languages will die.", "Nothing can be done."], 0, "inference"]],
    grammar: Object.assign({}, DHEDGE, { spots: ["linguists estimate that as many as half of them could have disappeared", "usually", "may come under pressure", "perhaps", "may choose", "may be spoken", "may vanish", "to a large extent,"], practice: dhedgeP }) },
  { id: "di20-hope", band: 20, title: "Hope", type: "Poem", text: ["Hope is a small boat", "on a very wide sea,", "with a patched sail and one oar", "and no map at all,", "rowing anyway.", "Hope is the green shoot", "in the crack of the pavement,", "the one light left on", "in a tower block at midnight,", "the voice on the phone that says", "I'm coming.", "Hope is not loud.", "It does not need to be.", "It only needs", "to keep going."],
    vocab: { patched: "mended with pieces of material" },
    questions: [["What is hope first compared to?", ["a small boat on a very wide sea", "a bird", "a candle"], 0, "language"], ["What does the boat not have?", ["a map", "a sail", "an oar"], 0, "retrieval"], ["What does \"the green shoot in the crack of the pavement\" suggest about hope?", ["It can grow even in hard places.", "It is a weed.", "It is easily crushed."], 0, "language"], ["What does the poet say hope does not need to be?", ["loud", "strong", "small"], 0, "retrieval"], ["What is the main idea of the poem?", ["Hope is quiet but keeps going even against the odds.", "Hope is impossible.", "Hope is only for sailors."], 0, "summarising"]],
    grammar: Object.assign({}, DFIG, { spots: ["Hope is a small boat", "on a very wide sea,", "Hope is the green shoot", "in the crack of the pavement,", "the one light left on", "Hope is not loud."], practice: dfigP }) },
  { id: "di20-museum", band: 20, title: "Should Museums Return Objects?", type: "Argument", text: ["Many of the world's great museums contain objects that were taken from other countries during periods of war or empire. Increasingly, the countries from which these objects came are asking for them to be returned. Should museums agree?", "The case for return is, in many instances, compelling. Some objects were taken by force, often from communities that had no means of resisting. For those communities, the objects are not simply works of art; they are part of their history, identity and, in some cases, religious life. Keeping them in a foreign museum, however well cared for, can feel like the continuation of an old injustice.", "Those who oppose return raise several concerns. They argue that large museums allow millions of visitors from around the world to see and learn from these objects side by side. They also worry that, if every object were returned, the great museums would be emptied.", "These arguments deserve to be taken seriously. Yet neither seems strong enough to outweigh the claims of the people to whom the objects originally belonged. Shared exhibitions, long-term loans and digital collections offer ways for objects to be both returned and widely seen.", "Ultimately, the question is one of fairness. Where an object was taken without consent, and where its original owners ask for it back, it seems right that, in most cases, it should go home."],
    vocab: { injustice: "unfairness", consent: "permission", outweigh: "be more important than" },
    questions: [["What are some countries asking museums to do?", ["return objects taken from them", "build new museums", "lend them money"], 0, "retrieval"], ["Why are some objects important to their original communities?", ["They are part of their history, identity and religious life.", "They are very expensive.", "They are made of gold."], 0, "retrieval"], ["What is one argument against return?", ["Large museums let millions of people see the objects together.", "The objects are fake.", "Nobody wants them."], 0, "retrieval"], ["What is the writer's final position?", ["In most cases, objects taken without consent should be returned.", "No objects should ever be returned.", "Museums should be closed."], 0, "summarising"], ["Why does the writer say the opposing arguments \"deserve to be taken seriously\"?", ["to show fairness before explaining why they are not strong enough", "because the writer agrees with them completely", "to change the subject"], 0, "structure"]],
    grammar: Object.assign({}, DSTRUCT, { spots: ["Should museums agree?", "The case for return is, in many instances, compelling.", "Those who oppose return raise several concerns.", "These arguments deserve to be taken seriously. Yet", "Ultimately, the question is one of fairness."], practice: dstructP }) }
];
TEST_A[20] = DIAMOND_A; TEST_B[20] = DIAMOND_B; TEXTS.push(...DIAMOND_TEXTS);

/* =================== EARLY BANDS (1–4): adult-supported test and picture/caption books =================== */
/* EARLY BANDS (1–4) · FS1–FS2 · alongside Read Write Inc.
   The early test and early band checks are adult-supported: the child reads or talks, the adult taps ✓ or ✗. */
const EARLY = {
  1: { title: "Talking about pictures", adult: "Point to the picture and ask the question. Tap ✓ if the child answers in a sentence that makes sense (for example \"The dog is playing with a ball\"). Tap ✗ for single words, pointing only, or no answer.",
    items: [{ pic: "🐶⚽🌳", say: "What is the dog doing?" }, { pic: "👧🎂🎈", say: "What is happening here?" }, { pic: "🐱🥛", say: "What is the cat doing?" }, { pic: "👦🌧️☂️", say: "Tell me about the boy." },
            { pic: "🐦🪺🥚", say: "What can you see in the nest?" }, { pic: "👩‍🍳🍪", say: "What is she making?" }, { pic: "🚌👧👦🏫", say: "Where are the children going?" }, { pic: "🐸🪷💦", say: "What is the frog doing?" }] },
  2: { title: "Reading words", adult: "Ask the child to read the word. They may say the sounds first (c-a-t) and then the word. Tap ✓ if they read the whole word correctly. Tap ✗ if they cannot blend it or say a different word.",
    items: [{ word: "cat" }, { word: "sun" }, { word: "pig" }, { word: "bed" }, { word: "hop" }, { word: "net" }, { word: "map" }, { word: "dog" }] },
  3: { title: "Reading words and captions", adult: "Ask the child to read the word or sentence. Special friends (sh, ch, th, ng, nk) should be read as one sound. Tap ✓ if every word is read correctly.",
    items: [{ word: "ship" }, { word: "chat" }, { word: "thin" }, { word: "ring" }, { word: "pink" }, { word: "A big red bus." }, { word: "I can see a fish." }, { word: "The duck is wet." }] },
  4: { title: "Reading words and sentences", adult: "Ask the child to read the word or sentence. Set 2 sounds (ay, ee, igh, ow, oo, ar, or, air) should be read correctly. Tap ✓ if every word is read correctly.",
    items: [{ word: "play" }, { word: "tree" }, { word: "night" }, { word: "snow" }, { word: "moon" }, { word: "The cat can play in the sun." }, { word: "I see a star in the dark sky." }, { word: "We had fish and chips for tea." }] }
};
const EXPLAIN_EARLY = { 1: { focus: "Talking in sentences", explain: "Before children read, they learn to talk about pictures in full sentences: \"The bear is sleeping\", not just \"bear\". Retelling a story in order builds the language they will need for reading." },
  2: { focus: "Words and spaces", explain: "Writing is made of words, and there is a space between each word. Point to each word as you read it, one finger at a time." },
  3: { focus: "Capital letters and full stops", explain: "A sentence starts with a capital letter and ends with a full stop. The full stop tells us to pause before the next sentence." },
  4: { focus: "Joining ideas with 'and'", explain: "We can use and to join two ideas: \"The dog ran\" and \"the dog jumped\" become \"The dog ran and jumped.\"" } };
